parts.openscad_module:
$fn = 128;

cam_diameter  = 60;
eccentricity  = 10;
cam_thickness = 12;
bore_diameter = 8;
bore_clearance = 0.2;

module eccentric_cam() {
  difference() {
    cylinder(h = cam_thickness, d = cam_diameter, center = true);
    translate([eccentricity, 0, 0])
      cylinder(h = cam_thickness + 2, d = bore_diameter + bore_clearance, center = true, $fn = 64);
    translate([eccentricity + bore_diameter/2 + 3, 0, 0])
      rotate([90, 0, 0])
        cylinder(h = cam_diameter, d = 4.5, center = true, $fn = 32);
  }
}

eccentric_cam();
